package dev.metrobuilder.item.tool;
import dev.metrobuilder.selection.SelectionManager; import net.minecraft.item.*; import net.minecraft.server.network.ServerPlayerEntity; import net.minecraft.util.ActionResult; import net.minecraft.util.math.BlockPos;
public final class MoveToolItem extends Item { public MoveToolItem(Settings s){super(s.maxCount(1));} @Override public ActionResult useOnBlock(ItemUsageContext c){if(c.getWorld().isClient)return ActionResult.SUCCESS;if(c.getPlayer() instanceof ServerPlayerEntity p){if(p.isSneaking()){SelectionManager.cancelPending(p);return ActionResult.CONSUME;}if(!SelectionManager.requireUsable(p))return ActionResult.FAIL;BlockPos d=c.getBlockPos().offset(c.getSide());if(SelectionManager.stageOrConfirm(p, SelectionManager.ActionType.MOVE,d))SelectionManager.move(p,d);return ActionResult.CONSUME;}return ActionResult.PASS;} }
